ALTER TABLE procedimentos_agenda_inteligente_orus ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can view active procedures" ON procedimentos_agenda_inteligente_orus FOR SELECT USING (ativo = true); CREATE POLICY "Authenticated users can insert procedures" ON procedimentos_agenda_inteligente_orus FOR INSERT WITH CHECK (auth.uid() IS NOT NULL); CREATE POLICY "Users can update procedures they created" ON procedimentos_agenda_inteligente_orus FOR UPDATE USING (created_by_user_id = auth.uid()); CREATE POLICY "Users can delete procedures they created" ON procedimentos_agenda_inteligente_orus FOR DELETE USING (created_by_user_id = auth.uid());;
